<section class="admin-heading"><div><span class="eyebrow eyebrow-dark">ORDER MANAGEMENT</span><h1><?= e($order['order_code']) ?></h1><p>Dibuat <?= e(format_date($order['created_at'])) ?> · perubahan status disimpan pada riwayat pesanan.</p></div><a class="button button-outline" href="<?= e(route('admin-orders')) ?>">← Semua pesanan</a></section>
<div class="admin-grid order-admin-grid">
    <section class="data-panel"><h2>Informasi pembeli</h2><div class="admin-order-meta"><p><span>Nama</span><?= e($order['customer_name']) ?></p><p><span>Nomor telepon</span><?= e($order['customer_phone']) ?></p><p><span>Metode</span><?= $order['fulfillment_method'] === 'delivery' ? 'Delivery' : 'Ambil sendiri' ?></p><p><span>Alamat</span><?= $order['delivery_address'] ? nl2br(e($order['delivery_address'])) : '—' ?></p><p><span>Catatan</span><?= $order['notes'] ? nl2br(e($order['notes'])) : '—' ?></p></div>
        <h2 class="section-gap">Rincian pesanan</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Menu</th><th>Harga snapshot</th><th>Jumlah</th><th>Subtotal</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= e($item['product_name_snapshot']) ?></td><td><?= e(money($item['unit_price'])) ?></td><td><?= (int) $item['quantity'] ?></td><td><?= e(money($item['line_total'])) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><th colspan="3">Subtotal item</th><td><?= e(money($order['subtotal'])) ?></td></tr><tr><th colspan="3">Biaya delivery</th><td><?= e(money($order['delivery_fee'])) ?></td></tr><tr><th colspan="3">Total</th><td><strong><?= e(money($order['total_amount'])) ?></strong></td></tr></tfoot></table></div>
    </section>
    <div class="admin-side-stack">
        <section class="data-panel"><h2>Status pesanan</h2><p><span class="status-pill status-<?= e($order['order_status']) ?>"><?= e(order_status_label($order['order_status'])) ?></span></p>
            <?php if ($transitions !== []): ?><form method="post" action="<?= e(route('admin-order-status')) ?>" class="stack-form"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int) $order['id'] ?>"><label class="field"><span>Ubah menjadi</span><select name="order_status" required><?php foreach ($transitions as $status): ?><option value="<?= e($status) ?>"><?= e(order_status_label($status)) ?></option><?php endforeach; ?></select></label><label class="field"><span>Catatan <small>(opsional)</small></span><input name="note" maxlength="500"></label><button class="button button-primary button-wide" type="submit">Simpan status</button></form><?php else: ?><p class="muted">Status pesanan ini sudah final.</p><?php endif; ?>
            <?php if (in_array($order['order_status'], ['cancelled', 'rejected'], true)): ?><p class="refund-policy">Pengembalian dana tidak tersedia pada demo. Status ini hanya dapat diterapkan sebelum pembayaran dikonfirmasi.</p><?php endif; ?>
        </section>
        <section class="data-panel"><h2>Pembayaran</h2><p class="payment-method-label">Metode: <strong><?= e(payment_methods()[$order['payment_method']] ?? $order['payment_method']) ?></strong></p><p><span class="status-pill status-<?= e($order['payment_status']) ?>"><?= e(payment_status_label($order['payment_status'])) ?></span></p>
            <?php if (in_array($order['payment_status'], ['unpaid', 'awaiting_confirmation'], true) && !in_array($order['order_status'], ['rejected', 'cancelled'], true)): ?><div class="admin-payment-actions">
                <form method="post" action="<?= e(route('admin-payment-status')) ?>"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int) $order['id'] ?>"><input type="hidden" name="payment_status" value="paid"><button class="button button-primary button-wide" type="submit">Konfirmasi pembayaran</button></form>
                <?php if ($order['payment_status'] === 'awaiting_confirmation'): ?><form method="post" action="<?= e(route('admin-payment-status')) ?>" data-confirm="Tolak pembayaran simulasi ini? Stok baru kembali saat pesanan juga ditolak atau dibatalkan."><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int) $order['id'] ?>"><input type="hidden" name="payment_status" value="rejected"><button class="button button-outline button-wide" type="submit">Tolak pembayaran</button></form><?php endif; ?>
            </div><p class="summary-hint">Pembayaran pada website ini adalah simulasi. Konfirmasi hanya mencatat penerimaan demo.</p><?php else: ?><p class="muted">Status pembayaran tidak dapat diubah lagi.</p><?php endif; ?>
            <?php if ($order['payment_status'] === 'paid'): ?><p class="payment-date">Dikonfirmasi <?= e(format_date($order['payment_confirmed_at'])) ?></p><?php endif; ?>
        </section>
    </div>
</div>
<section class="data-panel log-panel"><h2>Log perubahan status</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Waktu</th><th>Jenis</th><th>Dari</th><th>Menjadi</th><th>Aktor</th><th>Catatan</th></tr></thead><tbody><?php foreach ($logs as $log): ?><tr><td><?= e(format_date($log['created_at'])) ?></td><td><?= $log['event_type'] === 'payment' ? 'Pembayaran' : 'Pesanan' ?></td><td><?= e($log['old_status'] ?: '—') ?></td><td><?= e($log['new_status']) ?></td><td><?= e($log['actor'] ?: 'Pembeli') ?></td><td><?= e($log['note'] ?: '—') ?></td></tr><?php endforeach; ?></tbody></table></div></section>
